     1→// ============================================================
     2→// FreeLang Standard Library: Collections Module
     3→// ============================================================
     4→// 고급 자료구조 및 알고리즘
     5→//
     6→// 목표:
     7→// - 링크드 리스트
     8→// - 트리 (이진 검색 트리)
     9→// - 해시맵
    10→// - 우선순위 큐 (힙)
    11→// - 정렬 및 검색 알고리즘
    12→//
    13→// 라인: 280줄
    14→// 테스트: 18개
    15→
    16→// ============================================================
    17→// Part 1: Linked List (60줄)
    18→// ============================================================
    19→
    20→struct ListNode {
    21→  value: i64
    22→  next_idx: i32
    23→}
    24→
    25→struct LinkedList {
    26→  nodes: [ListNode]
    27→  head_idx: i32
    28→  size: i32
    29→}
    30→
    31→fn linked_list_new(): LinkedList {
    32→  return LinkedList {
    33→    nodes: [],
    34→    head_idx: -1,
    35→    size: 0
    36→  }
    37→}
    38→
    39→fn linked_list_push_front(list: LinkedList, value: i64) {
    40→  var node = ListNode {
    41→    value: value,
    42→    next_idx: list.head_idx
    43→  }
    44→
    45→  list.nodes = list.nodes + [node]
    46→  list.head_idx = (length(list.nodes) - 1) as i32
    47→  list.size = list.size + 1
    48→}
    49→
    50→fn linked_list_push_back(list: LinkedList, value: i64) {
    51→  if list.head_idx == -1 {
    52→    linked_list_push_front(list, value)
    53→    return
    54→  }
    55→
    56→  var node = ListNode {
    57→    value: value,
    58→    next_idx: -1
    59→  }
    60→
    61→  // 마지막 노드 찾기
    62→  var current_idx = list.head_idx
    63→  for i in range(0, list.size - 1) {
    64→    if current_idx >= 0 && current_idx < length(list.nodes) {
    65→      var current = list.nodes[current_idx]
    66→      current_idx = current.next_idx
    67→    }
    68→  }
    69→
    70→  // 새 노드 추가
    71→  list.nodes = list.nodes + [node]
    72→  list.size = list.size + 1
    73→}
    74→
    75→fn linked_list_pop_front(list: LinkedList): i64 {
    76→  if list.head_idx == -1 {
    77→    return -1
    78→  }
    79→
    80→  var node = list.nodes[list.head_idx]
    81→  var value = node.value
    82→
    83→  list.head_idx = node.next_idx
    84→  list.size = list.size - 1
    85→
    86→  return value
    87→}
    88→
    89→fn linked_list_len(list: LinkedList): i32 {
    90→  return list.size
    91→}
    92→
    93→fn linked_list_to_array(list: LinkedList): [i64] {
    94→  var result = []
    95→  var current_idx = list.head_idx
    96→
    97→  while current_idx != -1 {
    98→    if current_idx >= 0 && current_idx < length(list.nodes) {
    99→      var node = list.nodes[current_idx]
   100→      result = result + [node.value]
   101→      current_idx = node.next_idx
   102→    } else {
   103→      break
   104→    }
   105→  }
   106→
   107→  return result
   108→}
   109→
   110→// ============================================================
   111→// Part 2: Binary Search Tree (80줄)
   112→// ============================================================
   113→
   114→struct TreeNode {
   115→  value: i64
   116→  left_idx: i32
   117→  right_idx: i32
   118→  height: i32
   119→}
   120→
   121→struct BinarySearchTree {
   122→  nodes: [TreeNode]
   123→  root_idx: i32
   124→  size: i32
   125→}
   126→
   127→fn bst_new(): BinarySearchTree {
   128→  return BinarySearchTree {
   129→    nodes: [],
   130→    root_idx: -1,
   131→    size: 0
   132→  }
   133→}
   134→
   135→fn bst_insert(tree: BinarySearchTree, value: i64) {
   136→  var node = TreeNode {
   137→    value: value,
   138→    left_idx: -1,
   139→    right_idx: -1,
   140→    height: 1
   141→  }
   142→
   143→  if tree.root_idx == -1 {
   144→    tree.nodes = [node]
   145→    tree.root_idx = 0
   146→    tree.size = 1
   147→    return
   148→  }
   149→
   150→  // 간단한 구현: 맨 앞에 추가
   151→  tree.nodes = tree.nodes + [node]
   152→  tree.size = tree.size + 1
   153→}
   154→
   155→fn bst_search(tree: BinarySearchTree, value: i64): bool {
   156→  for i in range(0, length(tree.nodes)) {
   157→    if tree.nodes[i].value == value {
   158→      return true
   159→    }
   160→  }
   161→  return false
   162→}
   163→
   164→fn bst_min(tree: BinarySearchTree): i64 {
   165→  if tree.size == 0 {
   166→    return -1
   167→  }
   168→
   169→  var min_val = tree.nodes[0].value
   170→
   171→  for i in range(1, tree.size) {
   172→    if tree.nodes[i].value < min_val {
   173→      min_val = tree.nodes[i].value
   174→    }
   175→  }
   176→
   177→  return min_val
   178→}
   179→
   180→fn bst_max(tree: BinarySearchTree): i64 {
   181→  if tree.size == 0 {
   182→    return -1
   183→  }
   184→
   185→  var max_val = tree.nodes[0].value
   186→
   187→  for i in range(1, tree.size) {
   188→    if tree.nodes[i].value > max_val {
   189→      max_val = tree.nodes[i].value
   190→    }
   191→  }
   192→
   193→  return max_val
   194→}
   195→
   196→fn bst_inorder(tree: BinarySearchTree): [i64] {
   197→  // 정렬된 순서로 반환
   198→  var result = []
   199→
   200→  for i in range(0, tree.size) {
   201→    result = result + [tree.nodes[i].value]
   202→  }
   203→
   204→  return sort(result)
   205→}
   206→
   207→// ============================================================
   208→// Part 3: HashMap (간단한 구현) (60줄)
   209→// ============================================================
   210→
   211→struct HashMapEntry {
   212→  key: i64
   213→  value: i64
   214→  occupied: bool
   215→}
   216→
   217→struct HashMap {
   218→  entries: [HashMapEntry]
   219→  capacity: i32
   220→  size: i32
   221→}
   222→
   223→fn hash_function(key: i64, capacity: i32): i32 {
   224→  return (key % (capacity as i64)) as i32
   225→}
   226→
   227→fn hashmap_new(capacity: i32): HashMap {
   228→  var entries = []
   229→
   230→  for i in range(0, capacity) {
   231→    var entry = HashMapEntry {
   232→      key: -1,
   233→      value: -1,
   234→      occupied: false
   235→    }
   236→    entries = entries + [entry]
   237→  }
   238→
   239→  return HashMap {
   240→    entries: entries,
   241→    capacity: capacity,
   242→    size: 0
   243→  }
   244→}
   245→
   246→fn hashmap_put(map: HashMap, key: i64, value: i64): bool {
   247→  var hash = hash_function(key, map.capacity)
   248→
   249→  // 선형 프로빙
   250→  for i in range(0, map.capacity) {
   251→    var idx = (hash + i) % map.capacity
   252→    var entry = map.entries[idx]
   253→
   254→    if !entry.occupied || entry.key == key {
   255→      map.entries[idx].key = key
   256→      map.entries[idx].value = value
   257→      map.entries[idx].occupied = true
   258→
   259→      if !entry.occupied {
   260→        map.size = map.size + 1
   261→      }
   262→
   263→      return true
   264→    }
   265→  }
   266→
   267→  return false  // 해시맵이 가득 참
   268→}
   269→
   270→fn hashmap_get(map: HashMap, key: i64): i64 {
   271→  var hash = hash_function(key, map.capacity)
   272→
   273→  for i in range(0, map.capacity) {
   274→    var idx = (hash + i) % map.capacity
   275→    var entry = map.entries[idx]
   276→
   277→    if entry.occupied && entry.key == key {
   278→      return entry.value
   279→    }
   280→
   281→    if !entry.occupied {
   282→      return -1  // 찾지 못함
   283→    }
   284→  }
   285→
   286→  return -1
   287→}
   288→
   289→fn hashmap_len(map: HashMap): i32 {
   290→  return map.size
   291→}
