   293→// ============================================================
   294→// Part 4: Priority Queue (Min Heap) (50줄)
   295→// ============================================================
   296→
   297→struct PriorityQueue {
   298→  items: [i64]
   299→  priorities: [i64]
   300→  size: i32
   301→}
   302→
   303→fn pq_new(): PriorityQueue {
   304→  return PriorityQueue {
   305→    items: [],
   306→    priorities: [],
   307→    size: 0
   308→  }
   309→}
   310→
   311→fn pq_parent_idx(idx: i32): i32 {
   312→  return (idx - 1) / 2
   313→}
   314→
   315→fn pq_left_child_idx(idx: i32): i32 {
   316→  return 2 * idx + 1
   317→}
   318→
   319→fn pq_right_child_idx(idx: i32): i32 {
   320→  return 2 * idx + 2
   321→}
   322→
   323→fn pq_push(pq: PriorityQueue, item: i64, priority: i64) {
   324→  pq.items = pq.items + [item]
   325→  pq.priorities = pq.priorities + [priority]
   326→  pq.size = pq.size + 1
   327→
   328→  // Bubble up
   329→  var idx = pq.size - 1
   330→  while idx > 0 {
   331→    var parent_idx = pq_parent_idx(idx)
   332→    if pq.priorities[idx] < pq.priorities[parent_idx] {
   333→      // Swap
   334→      var tmp_item = pq.items[idx]
   335→      var tmp_priority = pq.priorities[idx]
   336→
   337→      pq.items[idx] = pq.items[parent_idx]
   338→      pq.priorities[idx] = pq.priorities[parent_idx]
   339→
   340→      pq.items[parent_idx] = tmp_item
   341→      pq.priorities[parent_idx] = tmp_priority
   342→
   343→      idx = parent_idx
   344→    } else {
   345→      break
   346→    }
   347→  }
   348→}
   349→
   350→fn pq_pop(pq: PriorityQueue): i64 {
   351→  if pq.size == 0 {
   352→    return -1
   353→  }
   354→
   355→  var result = pq.items[0]
   356→
   357→  if pq.size == 1 {
   358→    pq.items = []
   359→    pq.priorities = []
   360→    pq.size = 0
   361→    return result
   362→  }
   363→
   364→  // 마지막 요소를 루트로 이동
   365→  pq.items[0] = pq.items[pq.size - 1]
   366→  pq.priorities[0] = pq.priorities[pq.size - 1]
   367→
   368→  var new_items = []
   369→  var new_priorities = []
   370→
   371→  for i in range(0, pq.size - 1) {
   372→    new_items = new_items + [pq.items[i]]
   373→    new_priorities = new_priorities + [pq.priorities[i]]
   374→  }
   375→
   376→  pq.items = new_items
   377→  pq.priorities = new_priorities
   378→  pq.size = pq.size - 1
   379→
   380→  return result
   381→}
   382→
   383→fn pq_len(pq: PriorityQueue): i32 {
   384→  return pq.size
   385→}
