   388→// Part 5: Sorting Algorithms (30줄)
   389→// ============================================================
   390→
   391→fn bubble_sort(arr: [i64]): [i64] {
   392→  var result = arr
   393→  var n = length(result)
   394→
   395→  for i in range(0, n) {
   396→    for j in range(0, n - 1 - i) {
   397→      if result[j] > result[j + 1] {
   398→        var tmp = result[j]
   399→        result[j] = result[j + 1]
   400→        result[j + 1] = tmp
   401→      }
   402→    }
   403→  }
   404→
   405→  return result
   406→}
   407→
   408→fn merge_sorted(left: [i64], right: [i64]): [i64] {
   409→  var result = []
   410→  var i = 0
   411→  var j = 0
   412→
   413→  while i < length(left) && j < length(right) {
   414→    if left[i] <= right[j] {
   415→      result = result + [left[i]]
   416→      i = i + 1
   417→    } else {
   418→      result = result + [right[j]]
   419→      j = j + 1
   420→    }
   421→  }
   422→
   423→  while i < length(left) {
   424→    result = result + [left[i]]
   425→    i = i + 1
   426→  }
   427→
   428→  while j < length(right) {
   429→    result = result + [right[j]]
   430→    j = j + 1
   431→  }
   432→
   433→  return result
   434→}
