    19→// 메모리 할당 상태 추적
    20→struct MemoryBlock {
    21→  addr: i64
    22→  size: i64
    23→  free: bool
    24→  next_idx: i32
    25→}
    26→
    27→// 간단한 메모리 할당자
    28→struct Allocator {
    29→  blocks: [MemoryBlock]
    30→  total_allocated: i64
    31→  total_freed: i64
    32→  peak_memory: i64
    33→}
    34→
    35→fn allocator_new(): Allocator {
    36→  return Allocator {
    37→    blocks: [],
    38→    total_allocated: 0,
    39→    total_freed: 0,
    40→    peak_memory: 0
    41→  }
    42→}
    43→
    44→fn allocator_alloc(alloc: Allocator, size: i64): i64 {
    45→  alloc.total_allocated = alloc.total_allocated + size
    46→
    47→  if alloc.total_allocated > alloc.peak_memory {
    48→    alloc.peak_memory = alloc.total_allocated
    49→  }
    50→
    51→  var block = MemoryBlock {
    52→    addr: alloc.total_allocated,
    53→    size: size,
    54→    free: false,
    55→    next_idx: -1
    56→  }
    57→
    58→  return block.addr
    59→}
    60→
    61→fn allocator_free(alloc: Allocator, addr: i64, size: i64) {
    62→  alloc.total_freed = alloc.total_freed + size
    63→}
    64→
    65→fn allocator_stats(alloc: Allocator): i64 {
    66→  var used = alloc.total_allocated - alloc.total_freed
    67→  return used
    68→}
