    74→// LRU 캐시 엔트리
    75→struct CacheEntry {
    76→  key: i64
    77→  value: i64
    78→  timestamp: i64
    79→  hit_count: i64
    80→}
    81→
    82→// LRU 캐시 (16 엔트리)
    83→struct LRUCache {
    84→  entries: [CacheEntry]
    85→  capacity: i32
    86→  size: i32
    87→  hits: i64
    88→  misses: i64
    89→}
    90→
    91→fn lru_cache_new(capacity: i32): LRUCache {
    92→  var entries = []
    93→
    94→  for i in range(0, capacity) {
    95→    var entry = CacheEntry {
    96→      key: -1,
    97→      value: -1,
    98→      timestamp: 0,
    99→      hit_count: 0
   100→    }
   101→    entries = entries + [entry]
   102→  }
   103→
   104→  return LRUCache {
   105→    entries: entries,
   106→    capacity: capacity,
   107→    size: 0,
   108→    hits: 0,
   109→    misses: 0
   110→  }
   111→}
   112→
   113→fn lru_cache_get(cache: LRUCache, key: i64): i64 {
   114→  for i in range(0, length(cache.entries)) {
   115→    var entry = cache.entries[i]
   116→    if entry.key == key {
   117→      cache.hits = cache.hits + 1
   118→      entry.hit_count = entry.hit_count + 1
   119→      entry.timestamp = 0  // 최근 사용으로 표시
   120→      return entry.value
   121→    }
   122→  }
   123→
   124→  cache.misses = cache.misses + 1
   125→  return -1
   126→}
   127→
   128→fn lru_cache_put(cache: LRUCache, key: i64, value: i64) {
   129→  // 이미 있으면 업데이트
   130→  for i in range(0, length(cache.entries)) {
   131→    var entry = cache.entries[i]
   132→    if entry.key == key {
   133→      entry.value = value
   134→      entry.timestamp = 0
   135→      return
   136→    }
   137→  }
   138→
   139→  // 새로운 엔트리 추가
   140→  if cache.size < cache.capacity {
   141→    var idx = cache.size
   142→    cache.entries[idx].key = key
   143→    cache.entries[idx].value = value
   144→    cache.entries[idx].timestamp = 0
   145→    cache.size = cache.size + 1
   146→  } else {
   147→    // 가장 오래된 엔트리 제거 (간단한 구현)
   148→    var min_hit = 99999
   149→    var victim_idx = 0
   150→
   151→    for i in range(0, cache.capacity) {
   152→      if cache.entries[i].hit_count < min_hit {
   153→        min_hit = cache.entries[i].hit_count
   154→        victim_idx = i
   155→      }
   156→    }
   157→
   158→    cache.entries[victim_idx].key = key
   159→    cache.entries[victim_idx].value = value
   160→    cache.entries[victim_idx].hit_count = 0
   161→  }
   162→}
   163→
   164→fn lru_cache_hit_rate(cache: LRUCache): i64 {
   165→  var total = cache.hits + cache.misses
   166→  if total == 0 { return 0 }
   167→  return (cache.hits * 100) / total
   168→}
   169→
   170→fn lru_cache_stats(cache: LRUCache): [i64] {
   171→  return [cache.hits, cache.misses, lru_cache_hit_rate(cache)]
   172→}
