   175→// Part 3: Memory Pool for Allocation (70줄)
   176→// ============================================================
   177→
   178→struct MemoryPool {
   179→  block_size: i64
   180→  num_blocks: i64
   181→  used_blocks: i32
   182→  free_list: [i32]
   183→}
   184→
   185→fn memory_pool_new(block_size: i64, num_blocks: i64): MemoryPool {
   186→  var free_list = []
   187→
   188→  for i in range(0, num_blocks) {
   189→    free_list = free_list + [i as i32]
   190→  }
   191→
   192→  return MemoryPool {
   193→    block_size: block_size,
   194→    num_blocks: num_blocks,
   195→    used_blocks: 0,
   196→    free_list: free_list
   197→  }
   198→}
   199→
   200→fn memory_pool_alloc(pool: MemoryPool, size: i64): i64 {
   201→  if length(pool.free_list) == 0 {
   202→    return -1  // 할당 실패
   203→  }
   204→
   205→  // 첫 번째 자유 블록 반환
   206→  var block_idx = pool.free_list[0]
   207→
   208→  // free_list에서 제거
   209→  var new_free_list = []
   210→  for i in range(1, length(pool.free_list)) {
   211→    new_free_list = new_free_list + [pool.free_list[i]]
   212→  }
   213→  pool.free_list = new_free_list
   214→
   215→  pool.used_blocks = pool.used_blocks + 1
   216→
   217→  // 블록의 주소 반환
   218→  return (block_idx as i64) * pool.block_size
   219→}
   220→
   221→fn memory_pool_free(pool: MemoryPool, block_idx: i64) {
   222→  pool.free_list = pool.free_list + [block_idx as i32]
   223→  pool.used_blocks = pool.used_blocks - 1
   224→}
   225→
   226→fn memory_pool_utilization(pool: MemoryPool): i64 {
   227→  var used = pool.used_blocks as i64
   228→  var total = pool.num_blocks
   229→  return (used * 100) / total
   230→}
