    35→    p99_latency_us: 0,
    36→    throughput_rps: 0
    37→  }
    38→}
    39→
    40→fn cpu_metrics_record(metrics: CPUMetrics, latency_us: i64) {
    41→  metrics.total_calls = metrics.total_calls + 1
    42→
    43→  if latency_us < metrics.min_latency_us {
    44→    metrics.min_latency_us = latency_us
    45→  }
    46→
    47→  if latency_us > metrics.max_latency_us {
    48→    metrics.max_latency_us = latency_us
    49→  }
    50→
    51→  // 단순화: 평균 업데이트
    52→  metrics.avg_latency_us = (metrics.avg_latency_us + latency_us) / 2
    53→}
