   127→// Part 2: Service Level Objectives (SLO) (80줄)
   128→// ============================================================
   129→
   130→struct SLOTarget {
   131→  name: string
   132→  metric_type: i32  // 0=latency, 1=throughput, 2=availability
   133→  threshold: i64
   134→  period_sec: i64
   135→  satisfaction: i64  // 0-100
   136→}
   137→
   138→fn slo_target_new(name: string, metric_type: i32, threshold: i64): SLOTarget {
   139→  return SLOTarget {
   140→    name: name,
   141→    metric_type: metric_type,
   142→    threshold: threshold,
   143→    period_sec: 3600,
   144→    satisfaction: 0
   145→  }
   146→}
   147→
   148→struct SLOTracker {
   149→  targets: [SLOTarget]
   150→  events: [i64]  // 성공/실패 기록
   151→  start_time: i64
   152→}
   153→
   154→fn slo_tracker_new(): SLOTracker {
   155→  return SLOTracker {
   156→    targets: [],
   157→    events: [],
   158→    start_time: 0
   159→  }
   160→}
   161→
   162→fn slo_tracker_add_target(tracker: SLOTracker, target: SLOTarget) {
   163→  tracker.targets = tracker.targets + [target]
   164→}
   165→
   166→fn slo_tracker_record_success(tracker: SLOTracker) {
   167→  tracker.events = tracker.events + [1]
   168→}
   169→
   170→fn slo_tracker_record_failure(tracker: SLOTracker) {
   171→  tracker.events = tracker.events + [0]
   172→}
   173→
   174→fn slo_tracker_calculate_satisfaction(tracker: SLOTracker): i64 {
   175→  if length(tracker.events) == 0 {
   176→    return 0
   177→  }
   178→
   179→  var success_count = 0 as i64
   180→
   181→  for i in range(0, length(tracker.events)) {
   182→    if tracker.events[i] == 1 {
   183→      success_count = success_count + 1
   184→    }
   185→  }
   186→
   187→  var total = length(tracker.events) as i64
   188→  return (success_count * 100) / total
   189→}
   190→
   191→fn slo_tracker_check_violation(tracker: SLOTracker, target_idx: i32): bool {
   192→  var satisfaction = slo_tracker_calculate_satisfaction(tracker)
   193→
   194→  if target_idx >= 0 && target_idx < length(tracker.targets) {
   195→    var target = tracker.targets[target_idx]
   196→    target.satisfaction = satisfaction
   197→
   198→    // SLO 위반 확인 (예: 99% 이상 필요)
   199→    if satisfaction < 99 {
   200→      return true
   201→    }
   202→  }
   203→
   204→  return false
   205→}
