   249→fn alert_manager_create_alert(mgr: AlertManager, name: string, severity: i32): i64 {
   250→  var alert = alert_new(mgr.next_alert_id, name, severity)
   251→  mgr.alerts = mgr.alerts + [alert]
   252→
   253→  var alert_id = mgr.next_alert_id
   254→  mgr.next_alert_id = mgr.next_alert_id + 1
   255→
   256→  return alert_id
   257→}
   258→
   259→fn alert_manager_trigger(mgr: AlertManager, alert_id: i64): bool {
   260→  for i in range(0, length(mgr.alerts)) {
   261→    var alert = mgr.alerts[i]
   262→
   263→    if alert.id == alert_id {
   264→      alert.is_active = true
   265→      alert.triggered_at = 0  // 현재 타임스탬프
   266→      mgr.total_triggered = mgr.total_triggered + 1
   267→      return true
   268→    }
   269→  }
   270→
   271→  return false
   272→}
   273→
   274→fn alert_manager_resolve(mgr: AlertManager, alert_id: i64): bool {
   275→  for i in range(0, length(mgr.alerts)) {
   276→    var alert = mgr.alerts[i]
   277→
   278→    if alert.id == alert_id && alert.is_active {
   279→      alert.is_active = false
   280→      alert.resolved_at = 0
   281→      mgr.total_resolved = mgr.total_resolved + 1
   282→      return true
   283→    }
   284→  }
   285→
   286→  return false
   287→}
