   302→// Part 4: Profiling & Histograms (70줄)
   303→// ============================================================
   304→
   305→struct HistogramBucket {
   306→  lower_bound: i64
   307→  upper_bound: i64
   308→  count: i64
   309→  percentage: i64
   310→}
   311→
   312→struct Histogram {
   313→  name: string
   314→  buckets: [HistogramBucket]
   315→  total_samples: i64
   316→  min_value: i64
   317→  max_value: i64
   318→}
   319→
   320→fn histogram_new(name: string): Histogram {
   321→  return Histogram {
   322→    name: name,
   323→    buckets: [],
   324→    total_samples: 0,
   325→    min_value: 999999999,
   326→    max_value: 0
   327→  }
   328→}
   329→
   330→fn histogram_add_bucket(hist: Histogram, lower: i64, upper: i64) {
   331→  var bucket = HistogramBucket {
   332→    lower_bound: lower,
   333→    upper_bound: upper,
   334→    count: 0,
   335→    percentage: 0
   336→  }
   337→
   338→  hist.buckets = hist.buckets + [bucket]
   339→}
   340→
   341→fn histogram_record(hist: Histogram, value: i64) {
   342→  hist.total_samples = hist.total_samples + 1
   343→
   344→  if value < hist.min_value {
   345→    hist.min_value = value
   346→  }
   347→
   348→  if value > hist.max_value {
   349→    hist.max_value = value
   350→  }
   351→
   352→  // 해당 버킷에 카운트 증가
   353→  for i in range(0, length(hist.buckets)) {
   354→    var bucket = hist.buckets[i]
   355→
   356→    if value >= bucket.lower_bound && value < bucket.upper_bound {
   357→      bucket.count = bucket.count + 1
   358→      bucket.percentage = (bucket.count * 100) / hist.total_samples
   359→      break
   360→    }
   361→  }
   362→}
   363→
   364→fn histogram_get_percentile(hist: Histogram, percentile: i64): i64 {
   365→  var target_count = (hist.total_samples * percentile) / 100
   366→  var cumulative = 0 as i64
   367→
   368→  for i in range(0, length(hist.buckets)) {
   369→    var bucket = hist.buckets[i]
   370→    cumulative = cumulative + bucket.count
   371→
   372→    if cumulative >= target_count {
   373→      return bucket.upper_bound
   374→    }
   375→  }
   376→
   377→  return hist.max_value
   378→}
