    82→struct Dependency {
    83→  name: string
    84→  version: string
    85→  required: bool
    86→  file_hash: i64
    87→}
    88→
    89→struct DependencyGraph {
    90→  nodes: [Dependency]
    91→  build_order: [string]
    92→  has_cycle: bool
    93→}
    94→
    95→fn dependency_graph_new(): DependencyGraph {
    96→  return DependencyGraph {
    97→    nodes: [],
    98→    build_order: [],
    99→    has_cycle: false
   100→  }
   101→}
   102→
   103→fn dependency_add(graph: DependencyGraph, dep: Dependency) {
   104→  graph.nodes = graph.nodes + [dep]
   105→}
   106→
   107→fn dependency_calculate_order(graph: DependencyGraph): [string] {
   108→  // 간단한 위상 정렬
   109→  var order = []
   110→
   111→  for i in range(0, length(graph.nodes)) {
   112→    var dep = graph.nodes[i]
   113→
   114→    // 의존성이 적은 순서대로 배치
   115→    var dep_count = length(dep.dependencies)
   116→
   117→    if dep_count == 0 {
   118→      order = order + [dep.name]
   119→    }
   120→  }
   121→
   122→  for i in range(0, length(graph.nodes)) {
   123→    var dep = graph.nodes[i]
   124→
   125→    if length(dep.dependencies) > 0 {
   126→      order = order + [dep.name]
   127→    }
   128→  }
   129→
   130→  graph.build_order = order
   131→  return order
   132→}
   133→
   134→fn dependency_has_cycle(graph: DependencyGraph): bool {
   135→  // 사이클 감지 (DFS)
   136→  var visited = []
   137→
   138→  for i in range(0, length(graph.nodes)) {
   139→    var dep = graph.nodes[i]
   140→
   141→    // 간단한 체크: 자기 자신에 의존하는지
   142→    for j in range(0, length(dep.dependencies)) {
   143→      if dep.dependencies[j] == dep.name {
   144→        graph.has_cycle = true
   145→        return true
   146→      }
   147→    }
   148→  }
   149→
   150→  return false
   151→}
   152→
   153→fn dependency_stats(graph: DependencyGraph): [i64] {
   154→  var total_deps = length(graph.nodes) as i64
   155→  var required_deps = 0 as i64
   156→
   157→  for i in range(0, length(graph.nodes)) {
   158→    if graph.nodes[i].required {
   159→      required_deps = required_deps + 1
   160→    }
   161→  }
   162→
   163→  return [total_deps, required_deps, graph.has_cycle as i64]
   164→}
