   240→// ============================================================
   241→
   242→struct BuildJob {
   243→  id: i64
   244→  target_name: string
   245→  status: i32  // 0=pending, 1=running, 2=completed, 3=failed
   246→  start_time: i64
   247→  end_time: i64
   248→  output_size: i64
   249→}
   250→
   251→struct BuildExecutor {
   252→  jobs: [BuildJob]
   253→  active_jobs: i32
   254→  max_parallel: i32
   255→  total_time_ms: i64
   256→}
   257→
   258→fn build_executor_new(max_parallel: i32): BuildExecutor {
   259→  return BuildExecutor {
   260→    jobs: [],
   261→    active_jobs: 0,
   262→    max_parallel: max_parallel,
   263→    total_time_ms: 0
   264→  }
   265→}
   266→
   267→fn build_executor_submit(executor: BuildExecutor, target_name: string): i64 {
   268→  var job = BuildJob {
   269→    id: length(executor.jobs) as i64,
   270→    target_name: target_name,
   271→    status: 0,  // pending
   272→    start_time: 0,
   273→    end_time: 0,
   274→    output_size: 0
   275→  }
   276→
   277→  executor.jobs = executor.jobs + [job]
   278→  return job.id
   279→}
   280→
   281→fn build_executor_can_run(executor: BuildExecutor): bool {
   282→  return executor.active_jobs < executor.max_parallel
   283→}
   284→
   285→fn build_executor_start_job(executor: BuildExecutor, job_id: i64) {
   286→  if job_id >= 0 && job_id < length(executor.jobs) {
   287→    executor.jobs[job_id].status = 1  // running
   288→    executor.active_jobs = executor.active_jobs + 1
   289→  }
   290→}
   291→
   292→fn build_executor_complete_job(executor: BuildExecutor, job_id: i64, output_size: i64) {
   293→  if job_id >= 0 && job_id < length(executor.jobs) {
   294→    executor.jobs[job_id].status = 2  // completed
   295→    executor.jobs[job_id].output_size = output_size
   296→    executor.active_jobs = executor.active_jobs - 1
   297→  }
   298→}
   299→
   300→fn build_executor_fail_job(executor: BuildExecutor, job_id: i64) {
   301→  if job_id >= 0 && job_id < length(executor.jobs) {
   302→    executor.jobs[job_id].status = 3  // failed
   303→    executor.active_jobs = executor.active_jobs - 1
   304→  }
   305→}
   306→
   307→fn build_executor_stats(executor: BuildExecutor): [i64] {
   308→  var completed = 0 as i64
   309→  var failed = 0 as i64
   310→  var total_output = 0 as i64
   311→
   312→  for i in range(0, length(executor.jobs)) {
   313→    var job = executor.jobs[i]
   314→
   315→    if job.status == 2 {
   316→      completed = completed + 1
   317→      total_output = total_output + job.output_size
   318→    } else if job.status == 3 {
   319→      failed = failed + 1
   320→    }
   321→  }
   322→
   323→  return [completed, failed, total_output]
   324→}
