   327→// Part 5: Artifact Optimization & Packaging (60줄)
   328→// ============================================================
   329→
   330→struct Artifact {
   331→  name: string
   332→  size_bytes: i64
   333→  original_size: i64
   334→  compression_ratio: i64
   335→  binary_size: i64
   336→}
   337→
   338→fn artifact_new(name: string, size_bytes: i64): Artifact {
   339→  return Artifact {
   340→    name: name,
   341→    size_bytes: size_bytes,
   342→    original_size: size_bytes,
   343→    compression_ratio: 0,
   344→    binary_size: 0
   345→  }
   346→}
   347→
   348→fn artifact_strip_debug_symbols(artifact: Artifact): i64 {
   349→  // 디버그 심볼 제거 시뮬레이션
   350→  var reduction = artifact.size_bytes / 3  // 약 33% 감소
   351→
   352→  artifact.binary_size = artifact.size_bytes - reduction
   353→  return reduction
   354→}
   355→
   356→fn artifact_compress(artifact: Artifact): i64 {
   357→  // 압축 시뮬레이션
   358→  var compressed_size = (artifact.binary_size * 40) / 100  // 60% 압축
   359→
   360→  artifact.compression_ratio = ((artifact.original_size - compressed_size) * 100) / artifact.original_size
   361→  artifact.size_bytes = compressed_size
   362→
   363→  return artifact.original_size - compressed_size
   364→}
   365→
   366→fn artifact_optimize(artifact: Artifact): i64 {
   367→  var total_saved = 0 as i64
   368→
   369→  // 1. 디버그 심볼 제거
   370→  total_saved = total_saved + artifact_strip_debug_symbols(artifact)
   371→
   372→  // 2. 코드 최적화 (시뮬레이션)
   373→  var opt_reduction = (artifact.binary_size * 5) / 100
   374→  artifact.binary_size = artifact.binary_size - opt_reduction
   375→  total_saved = total_saved + opt_reduction
   376→
   377→  // 3. 압축
   378→  total_saved = total_saved + artifact_compress(artifact)
   379→
   380→  return total_saved
   381→}
